(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["hu"] = {"ui":{"skip":"Ugrás a tartalomra","back":"← Vissza az AI-gile-hoz","lang.button":"Nyelv: {name}","lang.dialog":"Válassz nyelvet","lang.search":"Nyelvek keresése","lang.none":"Nincs találat","lang.notYet":"A(z) {name} még nincs lefordítva","theme.aria":"Témaváltás: világos, sötét vagy fekete","theme.toLight":"Váltás világos témára","theme.toDark":"Váltás sötét témára","theme.toBlack":"Váltás fekete témára (valódi fekete, kíméli az OLED-kijelzőt)","words.underline":"Húzd alá ezeket a szavakat az oldalon","words.underlineHelp":"Vidd az egeret egy pontozott szó fölé, vagy koppints rá, és megnézheted, mit jelent.","index.title":"AI-gile: az MI-fejlesztőcsapatod, egyetlen táblán","index.description":"Az AI-gile egy kanbantábla MI-s programozócsapatoknak. Ők dolgoznak, amíg te alszol; neked egyetlen rövid halom marad: amit el kell döntened, ki kell próbálnod és el kell fogadnod.","hero.logoAlt":"Az AI-gile tábla ikonja","hero.h1.html":"Az MI-fejlesztőcsapatod, egyetlen&nbsp;táblán.","hero.alpha":"🐣 Zárt pre-alfa","hero.alphaTitle":"Korai és befejezetlen: köszi, hogy kipróbálod!","hero.lede":"Ők építenek, amíg te alszol. Te egyetlen rövid halomra ébredsz: pár kérdés, pár kipróbálnivaló, egy-két lila gyémánt. Kattintasz, elfogadod, és mehetsz vissza a kávédhoz.","dl.windows":"Windows-alkalmazás","dl.browser":"Futtasd a böngészőben","dl.messenger":"📱 Messenger a telefonodra","dl.soon":"Hamarosan","dl.notify":"🔔 Szólj, ha megnyílik","dl.notifySmall":"Alfa vagy béta","hero.secondary":"Agilis, de a csapatnak nincs szüksége stand-up kávéra. (Stand-upot azért tartanak.)","pitch.h2":"AI-gile annyi szóban, amennyit csak szeretnél","pitch.lede":"Válassz hosszt, egy szótól 144-ig. Minden hossznak saját leírása van, éppen arra a méretre írva. Húzd a csúszkát, vagy használd a nyílbillentyűket.","pitch.rangeLabel":"Hossz szavakban","pitch.dice":"🎲 másik változat","pitch.words.one":"{n} szó","pitch.words.other":"{n} szó","pitch.letters.one":"{n} betű","pitch.letters.other":"{n} betű","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karakter","count.line.html.one":"{n} kártya van most a táblán","count.line.html.other":"{n} kártya van most a táblán","people.humans.html.one":"👥 {n} ember","people.humans.html.other":"👥 {n} ember","people.agents.html.one":"🤖 {n} ügynök","people.agents.html.other":"🤖 {n} ügynök","people.working.html.one":"⚡ {n} dolgozik éppen","people.working.html.other":"⚡ {n} dolgozik éppen","features.aria":"Mit tud","f.pile.h":"Egyetlen halom neked","f.pile.html":"A <b>Neked</b> oszlopban van minden, ami rád vár, az összes projektből: kérdések, kipróbálnivalók, olyan feladatok, amiket csak ember végezhet el. A sorod megmondja, mi jön és mennyi ideig tart.","f.sleep.h":"Csapatok, amelyek dolgoznak, amíg alszol","f.sleep.p":"Minden projektnek van egy lead-je és egy MI-ügynökökből álló csapata. Írj megjegyzést egy kártyához, a csapat felébred, elvégzi a munkát, és olyan lépésekkel adja vissza, amelyeket egy fáradt ember is követni tud.","f.tester.h":"Előbb egy MI-tesztelő ellenőrzi","f.tester.p":"Mielőtt bármi eljutna hozzád, a tesztelő az alkalmazás egy másolatában végigköveti a lépéseket, és képernyőképpel megmutatja, mit látott. Lapozd át az átment kártyákat, és fogadd el őket egy kattintással.","f.proof.h":"Bizonyíték, nem ígéret","f.proof.p":"Minden átadás megmutatja, mi változott: a fájlokat, a diffet, a képernyőképeket. Nem kell minden alkalmazást megnyitnod, hogy kiderüljön, kész van-e.","f.chat.h":"Beszélgess a lead-jeiddel","f.chat.p":"Discord-stílusú oldalsáv: projektenként egy ikon, lila gyémántok arra, ami téged vár. Küldj egy ötletet a lead-nek; ő kártyákká és tervvé alakítja, egy ✅ Go gombbal.","f.tidy.h":"Magától rendben tartja magát","f.tidy.p":"Az összetartozó kártyák eggyé olvadnak, a zavaros címek kijavulnak, a tokenellenőrzés pedig karcsún tartja a kódot. Kevesebb váltogatás, kevesebb gondolkodnivaló.","f.private.h":"A tiéd, a te gépeden","f.private.li1":"A tábla a saját gépeden fut, és csak neked válaszol.","f.private.li2":"Az emberek közti privát üzenetek végponttól végpontig titkosítottak.","f.private.li3":"Nincs fiók, nincs követő, nincs süti.","f.lang.h":"A te nyelveden","f.lang.p":"Több mint 120 nyelv, a hollandtól, a walestől és a japántól a kalózig, Yodáig és klingonig, gyors visszaváltással angolra a szakszavakhoz.","f.service.h":"Egy ötlettől egy igazi szolgáltatásig","f.service.p":"Építettél valamit MI-vel, amit most mások használnak? Jelöld meg szolgáltatásként, és a tábla segít jól üzemeltetni: elérhetőség-ellenőrzés, nyilvános állapotoldal, incidensek leírt áttekintéssel, Go-t igénylő változtatások, naponta ellenőrzött biztonsági mentések. A Súgó menet közben minden lépést megtanít.","msgr.h2":"AI-gile Messenger: a csapatod a zsebedben","msgr.p1":"Beszélgess az MI-csapatoddal a tábla megnyitása nélkül. Csetelj a projektjeid lead-jeivel és a barátaiddal, nézd meg egy kártya tesztlépéseit, és válaszolj rájuk, mindezt a telefonodról.","msgr.p2":"A párosításhoz olvass be egy QR-kódot a tábládon. Először jársz itt? Egy barátságos demóbeszélgetés körbevezet.","msgr.when":"Először Androidra, aztán webes változat telefonokra és iPhone-ra.","msgr.who":"A projekted lead-je","msgr.b1":"Kész a sötét mód javítása. Kéred a tesztlépéseket?","msgr.b2":"Igen, kérem!","msgr.b3":"1. Nyisd meg a Beállításokat. 2. Válaszd a Sötét lehetőséget. Jól néz ki?","tl.aria":"Idővonal az első beszélgetéstől az útitervig","tl.h2":"Az első beszélgetéstől a következő lépésekig","tl.lede":"Valódi dátumok és időpontok, a saját időzónádban. A mai nap után már csak a terv van, ígért dátumok nélkül.","tl.today":"Ma","tl.planned":"tervezett","tl.cards.one":"{n} kártya","tl.cards.other":"{n} kártya","join.h2":"Csatlakozz","join.lede":"Az AI-gile-t egy szakállas fura figura építi, AuDHD-vel és pár mentális egészségi csatával a háta mögött, meg sok türelmes ügynök. Egyelőre privát, zárt alfa a barátokkal. Szívesen kipróbálnád, ha megnyílik?","join.btn":"Érdeklődöm","join.small":"Írunk neked e-mailt, semmi mást","footer.tag":"AI-gile. Nincs követő, nincs süti, nincs stand-up kávé.","footer.licence":"Üzleti licenc","footer.status":"Állapot","footer.privacy":"Mit őrzünk meg","footer.thanks":"A hívásokért köszönet: ChilledChat","form.sending":"Küldés…","form.failed":"Ez nem sikerült: próbáld újra később.","form.offline":"Nem érem el az AI-gile-t: próbáld újra később.","form.keep":"Ezt csak arra használjuk, hogy válaszoljunk neked, utána töröljük. Nincs követő, nincs süti.","form.keepLink":"Mit őrzünk meg","interest.title":"AI-gile: szólj, ha megnyílik az alfa","interest.description":"Hagyd meg az e-mail-címedet, és megtudod, mikor nyílik meg az AI-gile zárt alfája vagy bétája.","interest.h1":"🔔 Szólj, ha megnyílik","interest.lede":"Az AI-gile zárt pre-alfában van. Hagyd meg az e-mail-címedet, és egyszer írunk, amikor lesz hely számodra.","interest.email":"Az e-mail-címed","interest.which":"Melyik teszt?","interest.alpha":"Zárt alfa: korai, nyers, sok változás","interest.beta":"Béta: stabilabb, később","interest.both":"Bármelyik, amelyik előbb jön","interest.submit":"Tegyetek fel a listára","interest.thanks":"Köszi! Felkerültél a listára.","licence.title":"AI-gile: üzleti licenc","licence.description":"A vállalkozásodban használnád az AI-gile-t? Kérj ingyenes üzleti licencet.","licence.h1":"📜 Üzleti licenc","licence.lede":"Munkahelyen használnád az AI-gile-t? Mondd el, kik vagytok és mivel foglalkoztok. Ha jót tesz a világnak, a licenc ingyenes.","licence.company":"Cég","licence.website":"Weboldal","licence.what":"Mivel foglalkoztok","licence.how":"Hogyan segít ez a világnak","licence.email":"E-mail","licence.submit":"Jelentkezem","licence.thanks":"Köszi! E-mailben válaszolunk.","status.title":"Az AI-gile állapota","status.h1":"Az AI-gile állapota","status.quiet":"Minden csendes","status.intro":"Működik most az AI-gile? Ez az oldal 5 percenként ellenőrzi a weboldalt, a táblamegosztást, a hívásokat és a letöltést.","status.up":"Működik ({ms} ms alatt válaszolt)","status.slow":"Nem válaszolt az utolsó ellenőrzésre, újrapróbálom","status.down":"Nem működik: nem válaszolt az utolsó két ellenőrzésre","status.svc.web":"Weboldal","status.svc.web.offers":"Ez az oldal: mi az AI-gile, és az érdeklődési űrlap","status.svc.boards":"Táblamegosztás","status.svc.boards.offers":"Nyilvános táblák, üzenetek barátok között és meghívók","status.svc.calls":"Hívások","status.svc.calls.offers":"Hang, videó és képernyőmegosztás az AI-gile-ban","status.svc.download":"Letöltés","status.svc.download.offers":"A Windows-telepítő és a meghívólinkek","status.checking":"Ellenőrzés…","status.offline":"Az állapotszolgáltatás most nem érhető el (újrapróbálom)","status.updated":"frissítve: {ago}","status.justNow":"épp most","status.min":"{n} perce","status.hours":"{n} órája","status.days":"{n} napja","privacy.title":"AI-gile: mit őrzünk meg","privacy.h1":"Mit őrzünk meg","privacy.lede":"Röviden: csak azt, amit elküldesz nekünk, és azt sem sokáig.","privacy.only":"Csak azt, amit elküldesz nekünk: amit beírsz egy űrlapba, például az e-mail-címedet. Semmi mást rólad.","privacy.sealed":"Lepecsételjük, így a szerverünk nem tudja elolvasni: még a böngésződben, mielőtt elindul (régebbi böngészőben abban a pillanatban, amikor megérkezik). Csak a saját táblánk tudja kinyitni.","privacy.server":"A szerverről törlődik, amint megérkezik a táblánkra. Ami 30 nap után is ott van, az mindenképp törlődik.","privacy.board":"A táblánkon csak addig tartjuk, amíg nem válaszolunk neked, aztán onnan is töröljük.","privacy.none":"Nincs követő, nincs süti, nincs analitika.","privacy.local":"A nyelved és a világos vagy sötét téma választása a saját böngésződben marad. Ezek soha nem jutnak el hozzánk.","privacy.ask":"Szeretnéd, hogy hamarabb eltűnjön? Válaszolj az e-mailünkre, és szólj.","live.h2":"Nézd, ahogy épül, élőben","live.caption":"Minden kártya rejtett: a munka alakját látod, nem a szavakat.","live.watching.one":"élő: {n} nézi","live.watching.other":"élő: {n} nézi","live.last.now":"Az utolsó kártya épp most mozdult","live.last.min.one":"Az utolsó kártya {n} perce mozdult","live.last.min.other":"Az utolsó kártya {n} perce mozdult","live.last.hour.one":"Az utolsó kártya {n} órája mozdult","live.last.hour.other":"Az utolsó kártya {n} órája mozdult","live.last.day.one":"Az utolsó kártya {n} napja mozdult","live.last.day.other":"Az utolsó kártya {n} napja mozdult","live.offline":"Az élő tábla kicsit pihen. Nézz vissza hamarosan.","live.cols":"Backlog|Teendő|Folyamatban|A csapat ellenőrzi|Neked kell tesztelni|A csapatnak|Kész"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotok.","Delegálva."]},{"n":2,"texts":["Robot kanban.","Rendezett ügynökök.","Ötletekből valóság."]},{"n":3,"texts":["Kanban robotoknak.","Ötletből funkció lesz.","Ingyenes ügynök-kanban."]},{"n":5,"texts":["Ügynökök által vezetett kanban tábla.","Te írod a kártyákat. Ők építenek.","Ingyenes, helyi, tesztelt, kicsit bolond."]},{"n":8,"texts":["Ingyenes kanban tábla, ahol az MI-ügynökök dolgoznak helyetted.","Leírsz egy ötletet. Az ügynökök megépítik. Te elfogadod.","Agilis munka egy embernek és sok türelmes robotnak."]},{"n":13,"texts":["Kanbantábla a gépeden, ahonnan az MI-ügynökök maguk viszik el a kártyákat.","Írj le egy ötletet. Ügynökök csapata megépíti. Egy tesztelő ellenőrzi.","Ingyenes, fiók és követés nélkül: egy tábla, néhány robot, és te irányítasz."]},{"n":21,"texts":["Az AI-gile egy kanbantábla az MI-s programozóügynökökkel való munkához. Ők viszik a kártyákat; te kipróbálod és elfogadod őket.","Minden projekt kap egy lead-et és egy MI-ügynökcsapatot. Írj megjegyzést bármelyik kártyához, és a csapat máris munkához lát.","Ingyenes, személyes teendőtábla, ami a saját gépeden fut. A dolgozók robotok. Aki igent mond, az te vagy."]},{"n":34,"texts":["Ötleteket teszel egy táblára. MI-ügynökök csapata működő funkciókká alakítja őket, kipróbálja, majd kipróbálható lépésekkel adja vissza neked. Semmi sem számít késznek, amíg te ezt ki nem mondod.","Az AI-gile egy házilag készült kanbantábla, amit Rich épített, rengeteg segítséggel azoktól az ügynököktől, akiket most irányít. Ingyenes, a gépeden fut, és barátokkal osztjuk meg, nem eladó.","Képzelj el egy hétköznapi kanbantáblát a Backlogtól a Kész oszlopig, csakhogy a kártyákat MI-ügynökök viszik. Beszámolnak az állásról, megkérdezik, ha elakadnak, és mindig megvárják a hüvelykujjadat felfelé."]},{"n":55,"texts":["Az AI-gile egy kanbantábla, amelynek csapata MI-ügynökökből áll. Minden projektnek van lead-je, aki megtervezi a munkát, és segítői, akik megépítik. Ha egy funkció elkészült, egy MI-tesztelő kipróbálja és képernyőképet készít, aztán a halmodra kerül. Fogadd el, vagy írj megjegyzést, és átdolgozzák. Nem kell közben mellettük állnod.","Úgy indult, hogy valaki egyszerre sok MI-programozós munkamenetet akart követni, aztán rendes táblává nőtte ki magát. A gépeden fut, nem kér fiókot, és nincsenek benne követők. Ingyenes barátoknak és bárkinek, akit érdekel. Befejezetlen is, úgyhogy számíts éles szélekre és egy-egy meglepetésre. Cserébe a tiéd, és nyugodtan alakíthatod.","Íme az őszinte változat. Az ötleteket továbbra is neked kell kitalálnod, az eredményt pedig neked kell ellenőrizned. Az AI-gile mindent csinál a kettő között: sorban tartja a kártyákat, a megfelelő ügynököt költi fel, ha megjegyzést írsz, pontosan megmutatja, mi változott, és mindezt egyetlen rövid halomba gyűjti neked."]},{"n":89,"texts":["Az AI-gile egy ingyenes kanbantábla, amit a saját gépeden futtatsz. Emberek helyett minden projektnek egy MI-ügynökcsapata van: egy lead, aki az ötleteidből kártyákat és tervet csinál, és segítők, akik prioritási sorrendben viszik a kártyákat. Ha elkészül valami, egy MI-tesztelő végigköveti a tesztlépéseket, és megmutatja, mit látott. Aztán az egész egy Neked nevű halomban vár. Elfogadod, vagy megjegyzést írsz, és a csapat újra nekifut. Semmi sem jut a Kész oszlopba nálad nélkül.","Néhány dolog, amire talán nem számítasz. Az éjjeliőr feltölti a Teendő oszlopot, amíg alszol, olyan kártyákat választva, amelyekhez nem kell a válaszod. A tokenszámláló megmutatja, mennyit használtak az ügynökök ma és ezen a héten, a Token nélküli mód pedig leállítja a költekezést. Üzenhetsz a barátaidnak, a privát üzenetek végponttól végpontig titkosítottak. A tábla nagyjából 120 nyelven beszél, köztük hollandul, flamandul, kalózul és klingonul. Mindez egy fillérbe sem kerül, és senki nem akarja rád sózni.","Az AI-gile egy kis személyes projekt, nem cég. Rich több MI-s programozási projektre akart vigyázni anélkül, hogy minden alkalmazást megnyitna, így az ügynökökkel építettek egy táblát, majd azzal a táblával építették meg önmaguk többi részét. Zárt pre-alfában van, vagyis többé-kevésbé működik egy maroknyi barátnak. Nincs árlap, nincs hírlevél, nincs növekedési terv. Nincs mögötte nagy terv, csak egy ember és egy csapat türelmes ügynök, akik élvezik a munkát. Ha hasznosnak hangzik, kérheted, hogy kipróbálhasd, amikor egy kicsit szélesebbre nyílik."]},{"n":144,"texts":["Az AI-gile egy kanbantábla egy embernek és sok MI-ügynöknek. A saját gépeden fut, és teljesen ingyenes. Projekteket adsz hozzá, és mindegyik kap egy lead-et meg egy kis csapatot. A lead-del csevegsz, kicsit Discord-módra, és elmeséled az ötletet; ő kártyákká és tervvé alakítja, aztán megvárja, hogy megnyomd a Go gombot. A csapat prioritási sorrendben halad a kártyákon, egy nyelvi modelleknek készült egyszerű parancssort használva. Mielőtt bármi visszajutna hozzád, egy MI-tesztelő végigköveti a lépéseket az alkalmazás egy másolatában, és képernyőképet csatol. A kész munka a változott fájlokkal és a diffel együtt a halmodra kerül. Elfogadod, vagy megjegyzést hagysz, a csapat pedig felébred és újra próbálkozik. Az egészből te csak azt látod, ami döntést kér. Kártyát csak te tehetsz a Kész oszlopba.","Nagyjából így néz ki egy nap az AI-gile-lal. Este hagysz pár megjegyzést: ez a gomb rossz helyen van, azt a listát rendezni kellene, lehetne sötét mód. Lefekszel aludni. Az ügynökök elolvassák a megjegyzéseket, elvégzik a módosításokat, letesztelik, és visszaadják neked. Ha kifogy a Teendő oszlop, az éjjeliőr feltölti a backlogból olyan kártyákkal, amelyekhez nem kell a válaszod. Reggel egyetlen rövid halom vár: néhány kérdés és néhány kipróbálnivaló, mindegyikhez lépések, amelyeket egy álmos ember is követ, és egy képernyőkép arról, hogy működik. Végigkattintod, elfogadod a jókat, a többit visszaküldöd. A tokenszámláló mutatja, mennyit fogyasztott mindez, a Token nélküli mód pedig a szűkös hetekre van. Nem kell közben ébren maradnod, és senki nem várja, hogy éjjel válaszolj. Aztán reggelizel, ebben az ügynökök még nem tudnak segíteni.","Először is: mi nem az AI-gile. Nem startup, nem eladó, és senki nem gyűjti az adataidat. Ingyenes tábla, ami a gépeden fut, fiók, követők és sütik nélkül. Ami viszont: egyetlen rendezett hely, ahol egyszerre látod az összes MI-s programozási projektet, ügynökcsapattal, amely a kártyákat viszi, és veled, aki a döntéseket hozod. Összevonja az összetartozó kártyákat, kijavítja a zavaros címeket, és figyeli, mennyire marad karcsú a kód. Nagyjából 120 nyelven beszél, a hollandtól és a flamandtól a kalózig és a klingonig. A barátok privátban és titkosítva üzenhetnek egymásnak. Nincs benne reklám, és senki nem hajt a felhasználókra. Rich és sok türelmes ügynök építette, többnyire önmagát használva. Zárt pre-alfában van, így néhol még nyers. Ha jókedvűnek hangzik, kérd szépen, és talán korán bejutsz."]}],"quips":{"1":"Egy szó. Merész. Talán túl merész is.","3":"Három szó. Már így őszintébb, mint a legtöbb termékoldal.","8":"Nyolc szó. Még mindig rövidebb egy stand-upnál.","21":"A hosszak egyébként story pointok. Hát persze, hogy azok.","55":"Ötvenöt szó. Amíg ezt olvastad, két kártya elkészült.","144":"Ez a hosszú. 233 nincs. Az ügynökök lefeküdtek aludni."}},"timeline":{"first-idea.name":"Az első ötlet","first-idea.line":"A legelső beszélgetés, még mielőtt egyetlen sor kód létezett volna.","first-board.name":"Az első tábla","first-board.line":"Egy tábla, amely a saját építését követi: kártyák, oszlopok, fogd és vidd, projektek.","team-roles.name":"Csapat és szerepek","team-roles.line":"Ügynökprofilok, csapatsablonok, terek és ki mit csinál.","install.name":"Telepítés és kiadások","install.line":"Egy zip, amit egy barát telepíthet, önfrissítés, csatornák és visszaállás.","usage-saver.name":"Használatspóroló","usage-saver.line":"Mérd, mibe kerülnek a futtatások, tartsd karcsún a kódot, spórolj a kereteddel.","friends.name":"Barátok és megosztás","friends.line":"Privát üzenetek, kevert továbbító, meghívók, szerepek és közös projektek.","languages.name":"Nyelvek","languages.line":"Minden képernyőszöveg egy nyelvi fájlban, elsőként hollandul és flamandul.","ai-tester.name":"MI-tesztelő","ai-tester.line":"Egy tesztelő előbb minden átadást ellenőriz, és megmutatja, mit látott.","website.name":"A weboldal","website.line":"Az aigile.lol, a teaser és ez az idővonal.","streaming.name":"Csevegés és streamelés","streaming.line":"Discord, Twitch, OBS, streamermód, GIF-ek és emojik.","no-ai.name":"MI nélküli kiadás","no-ai.line":"Tábla azoknak, akik MI nélkül programoznak, és nyilvános táblák.","night-watch.name":"Éjjeliőr","night-watch.line":"Egy őr és egy Scrum Master feladaton tartja a csapatokat, amíg alszol.","p-more.name":"Minden más","p-more.line":"Kisebb ötletek, amelyek még a sorukra várnak.","p-android.name":"Telefon és Android","p-android.line":"Érd el a táblád telefonról, aztán egy natív Android-alkalmazással.","p-release.name":"Alfa és tovább","p-release.line":"Zárt alfa, az éles oldal, aztán a béta.","p-languages.name":"Még több nyelv","p-languages.line":"Több mint száz nyelv, és elmerülős mód a tanulóknak.","p-engines.name":"Még több MI-motor","p-engines.line":"Válassz Claude-ot, Codexet vagy Geminit ügynökönként.","p-pro.name":"Profi gyakorlat","p-pro.line":"Kockázati címkék, merge-kapuk, incidenskártyák és védőkorlátok.","p-self.name":"Vigyázunk rád","p-self.line":"Fáradt mód, önmagadra figyelő emlékeztetők és a 4:20.","p-servers.name":"Szerverek és skálázás","p-servers.line":"Globális szerverbeállítások, szerepek és tervezés a növekedéshez.","p-livestream.name":"Streaming extrák","p-livestream.line":"Twitch-csevegés, egyéni emojik és nyilvános élő nézet."},"words":{"button":"📖 Szakszavak","h":"📖 Szómagyarázat","intro":"A szavak, amelyekkel az AI-gile-ban találkozol, érthetően: megépíteni, biztonságosan változtatni, működésben tartani a használóinak, és csapatként dolgozni az MI-vel.","search":"Szó keresése…","none":"Nincs ilyen szó.","close":"Bezárás","count":{"one":"{count} szó","other":"{count} szó"},"groups":[{"id":"build","name":"🛠️ Megépíteni"},{"id":"change","name":"🔀 Biztonságosan változtatni"},{"id":"run","name":"🛎️ Szolgáltatást üzemeltetni"},{"id":"team","name":"🤝 Csapatmunka (az MI-vel is)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"A projekt kódmappája és a commitok teljes története, ami általában a GitHubon is megvan.","also":["repository","repók"]},{"id":"branch","g":"build","word":"Branch","text":"A kód egy különálló munkavonala, hogy lehessen változtatni anélkül, hogy a fő verzióhoz hozzányúlnál.","also":["branchek","branchen"]},{"id":"commit","g":"build","word":"Commit","text":"A kód elmentett pillanatképe egy rövid megjegyzéssel arról, mi változott. Bármelyikhez bármikor visszatérhetsz.","also":["commitok","commitot"]},{"id":"push","g":"build","word":"Push","text":"Az elmentett pillanatképek (commitok) feltöltése erről a gépről a GitHubra, hogy legyen róluk mentés, és mások is lássák."},{"id":"merge","g":"build","word":"Merge","text":"Egy branch változtatásainak visszaolvasztása a fő verzióba."},{"id":"pr","g":"build","word":"Pull request","text":"Kérés, hogy egy branch változtatásait ellenőrizzék és olvasszák be a fő verzióba.","also":["PR"]},{"id":"refactor","g":"build","word":"Refaktorálás","text":"A kód rendezése anélkül, hogy változna, amit csinál: kisebb fájlok, érthetőbb nevek, kevesebb ismétlés."},{"id":"bug","g":"build","word":"Bug","text":"Valami, ami nem úgy működik, ahogy kellene.","also":["bugok","bugot","bugja"]},{"id":"test","g":"build","word":"Teszt","text":"Egy elkészült munka kipróbálása, hogy megnézd, azt csinálja-e, amit kértek, mielőtt elfogadod.","also":["tesztek","tesztet","tesztel","tesztelni","tesztelés","tesztelésre","tesztelendő","teszteld"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"A quality assurance, vagyis minőségbiztosítás rövidítése: az automatikus ellenőrzések, amelyek lefutnak, mielőtt bármi élesbe megy. Ha a QA piros, valami elbukott, és amíg nincs javítva, nem mehet élesbe.","also":["minőségellenőrzés","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Egy új verzió élesítése, például egy szerveren, ahol az emberek használják."},{"id":"release","g":"change","word":"Kiadás","text":"Kész munkák elnevezett csomagja, amely együtt megy élesbe, rövid jegyzetekkel arról, mi változott. A 🚀 Kiadások a kész kártyákból írja meg a jegyzeteket.","also":["kiadások","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Visszatérés az utolsó működő verzióra, ha egy új gondot okoz. Az AI-gile-ban ez ellenőrzőlistát készít a visszavonás lépéseiből, amelyeket minden változtatásra felírtak.","also":["roll back","visszaállás","visszagörgetés"]},{"id":"live","g":"change","word":"Éles","text":"Az igazi verzió, amit az emberek használnak, szemben egy kipróbálásra szánt másolattal. A fejlesztők production-nek is hívják.","also":["élesben","production","éles környezet"],"noTip":1},{"id":"change","g":"change","word":"Változtatás","text":"Tervezett változtatás valamin, amire az emberek számítanak, előre leírva: mit, miért, a kockázat, mikor és hogyan lehet visszavonni. Indíts egyet a 🔀 Változtatás kérése gombbal.","also":["változtatások","változtatási kérelem","change request"],"noTip":1},{"id":"risk","g":"change","word":"Kockázat","text":"Valami, ami félresikerülhet, pontozva aszerint, mennyire valószínű és mennyire lenne rossz. A ⚠️ Kockázatok egy listában tartja őket, a legmagasabb pontszámúval elöl, mindegyiket egy újranézési dátummal.","also":["kockázatok","kockázati nyilvántartás","risk register"]},{"id":"chgwin","g":"change","word":"Változtatási ablak","text":"Az időszakok, amikor változtatások élesbe mehetnek, például egy csendes kedd este. Ablakon kívül egy változtatási kártya nem zárható le, kivéve, ha vészhelyzet van.","also":["változtatási ablakok","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Gyors szavazás közvetlenül azelőtt, hogy egy változtatás élesbe megy: mindenki, akinek jóvá kell hagynia, Go-t vagy No go-t mond. Csak akkor megy tovább, ha egyetértenek.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Jóváhagyás","text":"Igenre várni, mielőtt a munka elkezdődik. Egy kártya, amit egy barát nyit, vagy egy változtatás, a ✅ Jóváhagyások között vár, amíg jóvá nem hagyod vagy el nem utasítod.","also":["jóváhagyások","approval"]},{"id":"quiettime","g":"change","word":"Csendes időszak","text":"Egy időszak, például egy stream, egy bemutató vagy az éjszaka, amikor semmi sem megy élesbe. A csapatok tovább dolgoznak és tesztelnek, de az élesítés vár, amíg véget nem ér. Máshol change freeze-nek hívják.","also":["csendes időszakok","változtatási tilalom","change freeze"]},{"id":"service","g":"run","word":"Szolgáltatás","text":"Valami, amit építettél és amire mások számítanak, például egy weboldal vagy egy app, és gondoskodnak róla, hogy működjön. Pipáld be: „Ez a projekt szolgáltatás”, és írd meg, mit kínál, kik használják és ki az ügyeletes.","also":["szolgáltatások","service"]},{"id":"uptime","g":"run","word":"Elérhetőség-ellenőrzés","text":"Automatikus ellenőrzés néhány percenként, hogy a szolgáltatásod még válaszol-e. Ha többször egymás után elbukik, az AI-gile magától nyit egy incidenskártyát.","also":["uptime","rendelkezésre állás","uptime check"]},{"id":"statuspage","g":"run","word":"Állapotoldal","text":"Nyilvános oldal, amely mutatja, működik-e egy szolgáltatás (zöld, narancs vagy piros) a legfrissebb hírrel, hogy a használói megnézhessék, ahelyett hogy kérdezgetnének.","also":["állapotoldalak","status page"]},{"id":"incident","g":"run","word":"Incidens","text":"Valami, ami épp most nem működik a használóinak, például leállt a weboldal. Egy 🔥 incidenskártya előrevág a sorban: az első, hogy újra működjön.","also":["incidensek","incident"]},{"id":"major","g":"run","word":"Súlyos incidens","text":"Nagy incidens: sok embert érint, vagy pénz vagy adat van veszélyben. Egy gomb minden csapatot ráállít (swarm), felébreszti az ügyeletest, és 30 percenként állapotjelentést kér.","also":["súlyos incidensek","major incident"]},{"id":"oncall","g":"run","word":"Ügyelet","text":"Te vagy az, aki válaszol, ha valami elromlik, akár éjjel is. Minden szolgáltatásnak van egy ügyeletes csapattagja, akit elsőként ébresztenek az incidensei miatt.","also":["ügyeletes","on call","on-call"]},{"id":"replyby","g":"run","word":"Válaszhatáridő","text":"Mennyit várhat egy kártya az első válaszra, például egy órát egy incidensnél. Utána piros órát kap, hogy semmi ne merüljön csendben feledésbe. Válaszcélnak is hívják.","also":["válaszhatáridők","válaszcél","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Rövid visszatekintés egy incidens után: mi történt, mi segített és min kell változtatni, anélkül hogy bárkit hibáztatnánk. Incidenst nem lehet lezárni nélküle.","also":["post-mortemek","postmortem","incidens utáni áttekintés"]},{"id":"problem","g":"run","word":"Probléma","text":"Egy vagy több incidens mögötti rejtett ok. Egy 🧩 problémakártya összegyűjti a vissza-visszatérő incidenseket, hogy megtalálják és végleg kijavítsák az okot.","also":["problémák","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Kiváltó ok","text":"Az igazi ok, amiért valami elromlott, nem csak az, amit rosszul működni láttál. Javítsd ki a kiváltó okot, és az incidens nem tér vissza.","also":["kiváltó okok","gyökérok","root cause"]},{"id":"workaround","g":"run","word":"Megkerülő megoldás","text":"Mód arra, hogy a dolgok működjenek, amíg kész nincs a valódi javítás, például újraindítani valamit, ha beragad. A problémakártyára írják fel, hogy senkinek ne kelljen újra kitalálnia.","also":["megkerülő megoldások","workaround"]},{"id":"knownerror","g":"run","word":"Ismert hiba","text":"Probléma, amelynek érthető az oka és van megkerülő megoldása, de még nincs kijavítva. Az 🧩 Ismert hibák listázza őket, hogy mindenki a megkerülő megoldást használja, ahelyett hogy újra ásna.","also":["ismert hibák","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Lépésről lépésre szóló útmutató egy ismert fajta baj kijavításához, hogy mindig ugyanúgy és gyorsan menjen. Egy nagy incidens után a csapat javasolhat egyet, amire te adod rá az OK-t.","also":["runbookok"]},{"id":"backup","g":"run","word":"Biztonsági mentés","text":"Az adataid korábbi, elmentett másolata, amire vissza lehet állni, ha valami elveszik vagy megsérül. Az AI-gile minden nap biztonsági mentést készít a tábláidról.","also":["biztonsági mentések","mentés","backup"]},{"id":"restore","g":"run","word":"Visszaállítás","text":"Adatok visszatöltése egy biztonsági mentésből. Egy mentés csak akkor ér igazán valamit, ha tudod, hogy visszaállítható, ezért érdemes néha kipróbálni.","also":["visszaállít","visszaállítva","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ötletek és munka, amelyek még nincsenek betervezve. Semmin sem dolgoznak ott, amíg át nem kerül a Teendő oszlopba."},{"id":"sprint","g":"team","word":"Sprint","text":"Rövid munkaszakasz (gyakran egy-két hét) egy megbeszélt kártyahalmazzal, amit be kell fejezni.","also":["sprintek","sprintet","sprintben"]},{"id":"standup","g":"team","word":"Stand-up","text":"Gyors egyeztetés: ki mit csinált, mit csinál ezután, és mi akadályozza.","also":["standup","stand-upok","standupok","stand-upot"]},{"id":"kanban","g":"team","word":"Kanban","text":"Oszlopokból álló tábla (Teendő, Folyamatban, Kész), amelyen a kártyák balról jobbra haladnak, ahogy a munka halad."},{"id":"wip","g":"team","word":"WIP-korlát","text":"Folyamatban lévő munka: legfeljebb ennyi kártya lehet egy oszlopban, hogy a csapat előbb befejezzen dolgokat, mielőtt újakba kezd.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"A csapat rövid ellenőrzőlistája arról, mit jelent a „kész”, például tesztelve és elmagyarázva, mielőtt egy kártyát átadnak neked. Az ikertestvére, a Definition of Ready, azt mondja meg, mikor elég világos egy kártya ahhoz, hogy el lehessen kezdeni.","also":["Definition of Ready","a kész meghatározása"]},{"id":"testpile","g":"team","word":"Tesztkupac","text":"A kész kártyák, amelyek arra várnak, hogy kipróbáld őket, egymás után. Fogadj el egyet, vagy küldd vissza egy megjegyzéssel, és jön a következő.","also":["tesztkupacok","test pile"]},{"id":"retro","g":"team","word":"Retro","text":"Visszatekintés arra, hogyan dolgozik a csapat, hogy megegyezzenek egy dologban, amit jobban csinálnak. Az AI-gile-ban a retro változtatást javasol a csapat munkamódjában, te pedig azt mondod: Mehet vagy Még nem.","also":["retrók","retrospektív","retrospective"]},{"id":"peerreview","g":"team","word":"Kódellenőrzés","text":"Egy második szempár: egy másik MI átnézi minden kártya munkáját, mielőtt hozzád ér, így kevesebb hiba csúszik át.","also":["peer review","code review","szakmai átnézés"]},{"id":"swarm","g":"team","word":"Swarm","text":"Mindenki a fedélzetre: minden csapat félreteszi a többi munkát, hogy egyetlen sürgős projekten segítsen, amíg rendbe nem jön. A többi projekt addig vár.","also":["swarming","raj"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Aki a munkát folyásban tartja: észreveszi az elakadt kártyákat, nógatja a csapatokat, és emlékeztet, mi vár rád. Az AI-gile-ban a Lead Scrum Master ezt minden projektben megteszi.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Ügynök","text":"Egy MI, amely önállóan dolgozik egy feladaton: olvassa a kódot, módosít, ellenőrzéseket futtat, és jelent.","also":["ügynökök","ügynököt","agent","agentek"]},{"id":"token","g":"team","word":"Token","text":"Az egység, amiben az MI-használatot számoljuk: nagyjából néhány betűnyi elolvasott vagy megírt szöveg. Minél kevesebb token, annál több marad a csomagodból.","also":["tokenek","tokent"]},{"id":"hook","g":"team","word":"Hook","text":"Egy kis parancs, amely magától lefut egy adott pillanatban, pl. amikor egy MI-munkamenet elindul, hogy a csapat meghallja a hozzászólásaidat.","also":["hookok","hookot"]}]}};
